// Fails if a component MDX page has no <Controls /> block.
// Our MDX pages replace the autogenerated docs page, so Controls only show up where we add them.
import { globSync, readFileSync } from 'node:fs';

const missing = globSync('src/components/**/*.mdx').filter(
  (file) => !readFileSync(file, 'utf8').includes('<Controls'),
);

if (missing.length > 0) {
  console.error('These MDX files are missing <Controls />. Add it right after <Primary />:');
  missing.forEach((file) => console.error(`  ${file}`));
  process.exit(1);
}

console.log('All component MDX files include <Controls />.');
